#!/usr/bin/env bash
# Install a docket runner on this machine.
#
#   curl -fsSL https://raw.githubusercontent.com/payneio/docket/main/harness/install.sh \
#     | bash -s -- --harness claude-code
#   ./install.sh --harness pi --dir ~/bin
#
# Writes ONE executable that contains everything: the runner, its library, and
# the wrapper for the assistant you named. It re-executes itself to invoke the
# wrapper, so the subprocess contract is unchanged -- the subprocess is just the
# same file wearing a different hat.
#
# GENERATED by harness/build-installer. Edit the sources, not this.
set -euo pipefail

HARNESS=""
DEST="${HARNESS_DIR:-$HOME/.local/bin}"
NAME=""

die() { printf 'install: %s\n' "$*" >&2; exit 1; }

while [ $# -gt 0 ]; do
  case "$1" in
    --harness) HARNESS="${2:-}"; shift 2 ;;
    --dir)     DEST="${2:-}"; shift 2 ;;
    --name)    NAME="${2:-}"; shift 2 ;;
    --list)    LIST=1; shift ;;
    -h|--help)
      sed -n '2,12p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) die "unknown option $1" ;;
  esac
done
src_lib() { cat <<'EOF_src_lib'
# Shared by the runner and by wrappers that want it. Sourced, never executed.

#: Where the sources are, when there are sources. A bundled runner defines
#: `write_outcome_tool` instead and never reads this -- but without a default
#: here, running from a checkout silently had no tool to offer at all, and the
#: only sign was an MCP server that failed to start.
_HARNESS_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd 2>/dev/null)" || _HARNESS_LIB_DIR="."
: "${HARNESS_TOOL_SRC:=$_HARNESS_LIB_DIR/tools/report-outcome}"

: "${DOCKET_URL:=http://127.0.0.1:9006}"
: "${DK_CRED:=$HOME/.docket/credential}"

#: The credential, from the environment or from a file.
#:
#: `DOCKET_API_KEY` first, because a new box is one `export` away from working
#: and a file is a thing to create, own and forget. If it turns out to be a
#: ticket (`dke_`) it is spent for a real credential on first use -- so a single
#: variable either *is* the identity or *buys* it, and nothing has to know which
#: in advance.
docket_credential() {
  local key="${DOCKET_API_KEY:-}"
  if [ -z "$key" ] && [ -s "${DOCKET_CREDENTIAL_FILE:-$HOME/.docket/credential}" ]; then
    key="$(cat "${DOCKET_CREDENTIAL_FILE:-$HOME/.docket/credential}")"
  fi
  case "$key" in
    dke_*) key="$(docket_enrol "$key")" ;;
  esac
  printf '%s' "$key"
}

#: Spend a ticket, keep what comes back. Once, and then never again -- the
#: credential is written where the next run will find it without the ticket.
docket_enrol() {  # <ticket>
  local file out token
  file="${DOCKET_CREDENTIAL_FILE:-$HOME/.docket/credential}"
  if [ -s "$file" ]; then cat "$file"; return; fi
  out="$(curl -s -X POST "$DOCKET_URL/enrol" -H "Authorization: Bearer $1" \
         -H 'Content-Type: application/json' \
         -d "$(jq -nc --arg l "${HARNESS_LABEL:-$(hostname -s)}" '{label:$l}')")"
  token="$(printf '%s' "$out" | jq -r '.token // empty')"
  if [ -z "$token" ]; then
    printf 'could not enrol: %s\n' "$out" >&2
    return 1
  fi
  mkdir -p "$(dirname "$file")" && chmod 700 "$(dirname "$file")"
  ( umask 077; printf '%s' "$token" > "$file" )
  printf 'enrolled as %s\n' "$(printf '%s' "$out" | jq -r .party)" >&2
  printf '%s' "$token"
}

ts() { date -Is; }
log() { printf '%s %s\n' "$(ts)" "$*" >&2; }

#: Every call carries the credential; nothing else identifies us. Resolved once
#: per process, because enrolling twice would mint two credentials for one agent.
DOCKET_KEY=""
dk() {
  [ -z "$DOCKET_KEY" ] && DOCKET_KEY="$(docket_credential)"
  curl -s -H "Authorization: Bearer $DOCKET_KEY" \
       -H 'Content-Type: application/json' "$@"
}

uri_escape() { printf %s "$1" | jq -sRr @uri; }

#: A directory name for a subject URI. Stable, readable, and collision-free
#: enough for a filesystem: the URI's own characters, with anything a path would
#: object to replaced. Two subjects that differ at all still differ here, because
#: nothing is truncated.
workspace_slug() { printf %s "$1" | tr -c 'a-zA-Z0-9._-' '-' | tr -s '-'; }

#: What a wrapper is told. The entry, the conversation so far, and a directory.
#: Deliberately not: the runner's configuration, the credential, or anything
#: about wild-life -- a wrapper that needed those would be one this contract
#: cannot swap out.
execution_request() {  # <entry-json> <workspace> <me>
  jq -n --argjson e "$1" --arg ws "$2" --arg me "$3" '{
    entry: {
      id: $e.id, subject: $e.subject, subject_label: $e.subject_label,
      terms: $e.terms, state: $e.state, requester: $e.requester,
      delegate: $e.delegate, expected_by: $e.expected_by
    },
    moves: [$e.moves[] | {seq, at, by, move, note}],
    workspace: $ws,
    me: $me
  }'
}

#: A serviceable prompt built from the request, for wrappers with nothing better.
#: Any wrapper is free to ignore this and write its own -- which is the point of
#: the prompt living here rather than in the runner, where it used to be one
#: string that assumed every assistant had the same tools.
default_prompt() {  # <request-json>
  printf '%s' "$1" | jq -r '
    "You have taken on the following, and are accountable for it.\n\n"
    + "  What is owed: " + (.entry.subject_label // .entry.subject) + "\n"
    + (if .entry.terms then "  Specifically:  " + .entry.terms + "\n" else "" end)
    + "  Reference:     " + .entry.subject + "\n"
    + "  Working dir:   " + .workspace + "\n\n"
    + (if (.moves | length) > 1 then
        "The conversation so far:\n"
        + ([.moves[] | "  " + .move + (if .note then " — " + .note else "" end)] | join("\n"))
        + "\n\n" else "" end)
    + "Do what you can now, in the working directory. Stop when you reach a\n"
    + "stable point rather than looping. If you need a decision from somebody,\n"
    + "say so plainly instead of guessing."'
}

#: The result, out of whatever the wrapper printed.
#:
#: The whole of stdout first, because `jq` pretty-prints by default and a wrapper
#: that forgets `-c` would otherwise have its result read as a bare `}`. Failing
#: that, the last line, so a wrapper may print freely and answer at the end.
result_of() {
  if printf '%s' "$1" | jq -e '.outcome' >/dev/null 2>&1; then printf '%s' "$1"; return; fi
  printf '%s' "$1" | tail -1
}

#: A well-formed refusal, so a wrapper that dies mid-run still says something the
#: register can hold. Silence is the failure the whole design is arranged against.
failed_result() { jq -nc --arg n "$1" '{outcome:"failed", note:$n}'; }

#: An outcome left by the `report_outcome` tool.
#:
#: The file is the tool's transport, not the assistant's contract -- an MCP
#: server is a subprocess and has no other way to hand an answer to the runner.
#: Assistants are asked for a block in their final response instead, because a
#: filesystem the runner can see is a thing not all of them have and a final
#: response is a thing all of them do.
#:
#: Consumed, not just read. A stale outcome from last week's run reported as this
#: run's would be worse than having none.
declared_outcome() {  # <workspace>
  local f="$1/.harness/outcome.json"
  [ -s "$f" ] || return 1
  if jq -e '.outcome | test("^(delivered|progressed|blocked|declined|failed)$")' "$f" >/dev/null 2>&1; then
    jq -c '{outcome, note: (.note // ""), question: (.question // "")}' "$f"
    rm -f "$f"
    return 0
  fi
  printf 'ignoring an outcome file that is not one: %s\n' "$(head -c 200 "$f")" >&2
  rm -f "$f"
  return 1
}

#: Put the outcome tool where the assistant's config can point at it.
#:
#: Written into the workspace rather than assumed to be beside us, because the
#: installed runner is one file and has no repository behind it. `write_tool` is
#: defined by the bundle; from a checkout the file is simply copied.
install_outcome_tool() {  # <workspace> -> path, or nothing
  local dest="$1/.harness/report-outcome"
  mkdir -p "$1/.harness" || return 1
  if declare -F write_outcome_tool >/dev/null 2>&1; then
    write_outcome_tool "$dest"
  elif [ -f "${HARNESS_TOOL_SRC:-}" ]; then
    cp -f "$HARNESS_TOOL_SRC" "$dest"
  else
    return 1
  fi
  # An unrunnable tool is worse than none: the assistant is offered a server
  # that fails to start, and nothing says why except a status nobody reads.
  chmod +x "$dest" 2>/dev/null || return 1
  [ -s "$dest" ] || return 1
  printf '%s' "$dest"
}

#: Validate and tidy an outcome object, or fail.
#:
#: Shared so that every channel is held to the same shape -- a `blocked` with no
#: question is as useless arriving in a response as it is in a tool call.
normalise_outcome() {  # <json>
  printf '%s' "$1" | jq -ce '
    select(.outcome | type == "string")
    | select(.outcome | test("^(delivered|progressed|blocked|declined|failed)$"))
    | {outcome, note: ((.note // "") | tostring), question: ((.question // "") | tostring)}
    | select(.outcome != "blocked" or .question != "")
  ' 2>/dev/null
}

#: The outcome the assistant stated in its final response.
#:
#: The one channel every assistant has. Not all of them can write a file the
#: runner will ever see -- a hosted agent, a sandboxed one, anything behind a
#: gateway -- but all of them answer, so this is the floor that the tool and the
#: file sit above rather than the other way round.
#:
#: Read as a fenced block tagged `outcome`, and failing that as a bare JSON
#: object on its own line. The **last** one wins, so an assistant that quotes the
#: format earlier while explaining itself is not taken at its example.
response_outcome() {  # <final response text>
  local text="$1" block line
  block="$(printf '%s\n' "$text" | awk '
    /^[[:space:]]*```[[:space:]]*outcome[[:space:]]*$/ { inb=1; buf=""; next }
    inb && /^[[:space:]]*```/                          { inb=0; last=buf; next }
    inb                                                { buf = buf $0 "\n" }
    END { printf "%s", last }')"
  if [ -n "$block" ]; then
    normalise_outcome "$block" && return 0
  fi
  line="$(printf '%s\n' "$text" | grep -oE '\{[^{}]*"outcome"[^{}]*\}' | tail -1)"
  [ -n "$line" ] && normalise_outcome "$line" && return 0
  return 1
}

#: Keep an assistant's raw stdout when HARNESS_DEBUG is set.
#:
#: Every wrapper guesses at an undocumented output shape, and when a guess is
#: wrong the only symptom is a strange note in the register -- by which point the
#: output that would explain it is gone. This keeps it.
debug_dump() {  # <workspace> <name> <text>
  [ -n "${HARNESS_DEBUG:-}" ] || return 0
  mkdir -p "$1/.harness/raw" 2>/dev/null || return 0
  printf '%s' "$3" > "$1/.harness/raw/$2"
  printf 'raw %s kept at %s/.harness/raw/%s\n' "$2" "$1" "$2" >&2
}
EOF_src_lib
}

src_runner() { cat <<'EOF_src_runner'
#!/usr/bin/env bash
# Turn "it is my turn" into one invocation of a wrapper, and what it returns
# into a move.
#
# This is what is left of fleetix's reference-agent once everything that knew
# about a particular assistant is gone. What it knows: how to ask docket what is
# owed, how to keep a directory, how to run a subprocess, and how to write down
# what happened. It does not know what a wrapper does, what a subject means, or
# what finishing looks like.
#
# What it deliberately no longer does:
#   - accept work before looking at it. Accepting is a promise, and the previous
#     version made it on the assistant's behalf before the assistant had seen
#     anything, which left a refusal unexpressible.
#   - decide that finishing means a row changed in wild-life. That was true of
#     one deployment and became a rule for everybody. Now it is a verifier, and
#     there is usually no verifier.
#   - build the prompt. Different assistants want different prompts; the one
#     that used to live here assumed every assistant had the same MCP tools.
#
# `set -e` is intentionally NOT used: nearly every step here has a considered
# failure path, and an early exit would skip the part that reports it.
set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=harness/lib.sh
. "$HERE/lib.sh"

: "${HARNESS_WRAPPER:?set HARNESS_WRAPPER to the wrapper to invoke}"
: "${HARNESS_WORKSPACES:=$HOME/workspaces}"
: "${HARNESS_STATE:=$HOME/.harness}"
: "${HARNESS_VERIFIER:=}"
: "${HARNESS_AGENTS_MD:=$HERE/AGENTS.md}"
NAME="$(basename "$HARNESS_WRAPPER")"

mkdir -p "$HARNESS_STATE/logs" "$HARNESS_WORKSPACES" || exit 1

# One tick at a time. A run can outlast the interval that started it, and two
# ticks working the same entry would race each other into the same directory.
exec 9>"$HARNESS_STATE/lock"
flock -n 9 || { log "$NAME busy, skipping this tick"; exit 0; }

ME="$(dk "$DOCKET_URL/me" | jq -r '.party // empty')"
if [ -z "$ME" ]; then
  # Never guess. An unreachable register is not an empty one, and doing the work
  # anyway is how an agent ends up acting on something nobody asked it for.
  log "$NAME cannot reach docket at $DOCKET_URL — doing nothing"
  exit 1
fi

open="$(dk "$DOCKET_URL/entries?party=$(uri_escape "$ME")&open_only=true")"
# Mine to answer: I am the delegate, it is my move, and I am not waiting on a
# question I have already asked. `whose_turn` is the register's own rule -- a
# party that has just spoken is waiting, not stalling -- so it is read here
# rather than re-derived, which is how the two came to disagree before.
todo="$(printf '%s' "$open" | jq -c '[.[]
  | select(.your_role == "delegate")
  | select(.whose_turn == "delegate")
  | select(.is_blocked | not)
  | select(.state == "offered" or .state == "accepted")]')"

count="$(printf '%s' "$todo" | jq 'length')"
[ "$count" = "0" ] && { log "$NAME nothing to answer"; exit 0; }
log "$NAME has $count to answer"

move() {  # <entry-id> <move> [note] [extra-json]
  local extra body
  extra="${4:-}"; [ -z "$extra" ] && extra='{}'
  body="$(jq -n --arg m "$2" --arg n "${3:-}" --argjson x "$extra" \
          '{move:$m} + (if $n=="" then {} else {note:$n} end) + $x')"
  dk -o /dev/null -w '%{http_code}' -X POST "$DOCKET_URL/entries/$1/moves" -d "$body"
}

#: Ask the requester something, and record that we are waiting on the answer.
#: A question is an entry in the other direction -- the same loop, and it stays
#: outstanding until somebody answers it.
ask() {  # <entry-json> <question> -> question entry id
  local subject requester label
  subject="$(printf '%s' "$1" | jq -r '.subject')"
  requester="$(printf '%s' "$1" | jq -r '.requester')"
  label="$(printf '%s' "$1" | jq -r '.subject_label // empty')"
  dk -X POST "$DOCKET_URL/entries" -d "$(jq -n \
      --arg s "$subject" --arg d "$requester" --arg t "$2" --arg l "$label" \
      '{subject:$s, delegate:$d, terms:$t}
       + (if $l=="" then {} else {subject_label:$l} end)')" \
    | jq -r '.id // empty'
}

while read -r entry; do
  [ -z "$entry" ] && continue
  eid="$(printf '%s' "$entry" | jq -r '.id')"
  subject="$(printf '%s' "$entry" | jq -r '.subject')"
  state="$(printf '%s' "$entry" | jq -r '.state')"

  ws="$HARNESS_WORKSPACES/$(workspace_slug "$subject")"
  mkdir -p "$ws/.harness" || { log "$NAME cannot make $ws"; continue; }

  # The instructions go in every workspace, refreshed each run so an edit to
  # them reaches every agent without anybody redeploying anything. They are how
  # an assistant knows to declare its outcome instead of being guessed at, and
  # `CLAUDE.md` is a copy rather than a symlink because not every tool follows
  # one out of a directory it was told to work in.
  if declare -F write_agents_md >/dev/null 2>&1; then
    write_agents_md "$ws/AGENTS.md"          # bundled: carried inside this file
    cp -f "$ws/AGENTS.md" "$ws/CLAUDE.md" 2>/dev/null
  elif [ -n "${HARNESS_AGENTS_MD:-}" ] && [ -f "$HARNESS_AGENTS_MD" ]; then
    cp -f "$HARNESS_AGENTS_MD" "$ws/AGENTS.md" 2>/dev/null
    cp -f "$HARNESS_AGENTS_MD" "$ws/CLAUDE.md" 2>/dev/null
  fi
  # Never carry an outcome across runs: the wrapper consumes it, but a wrapper
  # that died before reading one would leave it to be read as this run's answer.
  rm -f "$ws/.harness/outcome.json"

  request="$(execution_request "$entry" "$ws" "$ME")"
  runlog="$HARNESS_STATE/logs/$(date +%Y%m%d-%H%M%S)-${eid:0:8}.log"

  log "$NAME -> $NAME wrapper for ${eid:0:8} ($state) in $ws"
  out="$(printf '%s' "$request" | HARNESS_ROLE=wrapper "$HARNESS_WRAPPER" 2>>"$runlog")"
  rc=$?
  result="$(result_of "$out")"
  # A wrapper that died, or printed something that is not a result, still has to
  # produce one. What must not happen is nothing: a run that changes the register
  # in no way and tells only a log file is the failure a shared record exists to
  # make visible.
  if [ $rc -ne 0 ] || ! printf '%s' "$result" | jq -e '.outcome' >/dev/null 2>&1; then
    tailed="$(tail -c 200 "$runlog" 2>/dev/null | tr -d '\000' | tr '\n' ' ')"
    result="$(failed_result "wrapper exited $rc: ${tailed:-no output}")"
  fi

  outcome="$(printf '%s' "$result" | jq -r '.outcome')"
  note="$(printf '%s' "$result" | jq -r '.note // empty' | head -c 400)"
  question="$(printf '%s' "$result" | jq -r '.question // empty')"

  # A claim of completion is checked, when there is anything to check it with.
  if [ "$outcome" = "delivered" ] && [ -n "$HARNESS_VERIFIER" ]; then
    if ! why="$(printf '%s' "$request" | "$HARNESS_VERIFIER" 2>&1)"; then
      log "$NAME ${eid:0:8} claimed delivered; verifier disagreed"
      outcome="progressed"
      note="said it was finished; ${why:-the verifier disagreed}"
    fi
  fi

  # Accepting is a promise, so it is made here and only because the wrapper
  # chose to work -- never in advance of it looking.
  if [ "$state" = "offered" ] && [ "$outcome" != "declined" ] && [ "$outcome" != "failed" ]; then
    move "$eid" accept "picked up by $NAME" >/dev/null
  fi

  case "$outcome" in
    declined)
      move "$eid" decline "${note:-declined}" >/dev/null
      log "$NAME declined ${eid:0:8}" ;;
    delivered)
      move "$eid" deliver "${note:-delivered}" >/dev/null
      log "$NAME delivered ${eid:0:8}" ;;
    blocked)
      qid=""
      [ -n "$question" ] && qid="$(ask "$entry" "$question")"
      if [ -n "$qid" ]; then
        move "$eid" update "${note:-blocked}" "$(jq -n --arg b "$qid" '{blocked_on:$b}')" >/dev/null
        log "$NAME ${eid:0:8} blocked; asked the requester"
      else
        # Say it anyway. A blocker recorded badly beats one recorded nowhere.
        move "$eid" update "${note:-blocked}${question:+ — needs: $question}" >/dev/null
        log "$NAME ${eid:0:8} blocked; no question opened"
      fi ;;
    progressed|failed|*)
      move "$eid" update "${note:-$outcome}" >/dev/null
      log "$NAME ${eid:0:8} $outcome — left $state, reported" ;;
  esac
done < <(printf '%s' "$todo" | jq -c '.[]')

log "$NAME done"
EOF_src_runner
}

src_agents() { cat <<'EOF_src_agents'
# Working here

This directory belongs to one piece of work. Something was offered to you, you
took it on, and this is where you do it. The directory persists: if you are
asked about this again next week, you will be back here with whatever you left.

**You do not need to know anything about the register that sent you.** You will
not be asked to poll it, read it, or report to it. Something else does that, and
it does it from what you say below.

## Say what happened before you stop

If you have a `report_outcome` tool, call it. Otherwise **end your final
response** with a fenced block, and nothing after it:

````
```outcome
{"outcome": "delivered", "note": "One line. This is what a person reads later."}
```
````

`outcome` is one of:

| | when |
|---|---|
| `delivered` | you believe the thing that was asked for is done |
| `progressed` | you did some of it and it is not finished |
| `blocked` | you cannot go further without an answer from somebody |
| `declined` | this is not yours to do, or you should not be the one doing it |
| `failed` | you could not work — a broken tool, a missing dependency |

When you are `blocked`, the question is required:

````
```outcome
{"outcome": "blocked",
 "note": "Cannot pick between two schemas without knowing the retention rule.",
 "question": "Should old rows be deleted or archived after 90 days?"}
```
````

That question is **opened as a real request to the person who asked you**, and
stays outstanding until they answer it. It is not a note in a log. So ask it the
way you would ask a colleague: one specific thing you need, not a summary of
your confusion.

## Why this matters more than it looks

Without it, whatever ran you has to guess your outcome by reading your prose for
words like "blocked". That works until it doesn't, and when it fails it fails
silently in the expensive direction — work recorded as progressing while it is
stuck, or as finished while it is not.

Two things follow:

- **`declined` is a real answer and you are allowed to give it.** If this was
  offered to you wrongly, say so. Refusing is not failing. What must not happen
  is that you attempt something out of scope because refusing was not an option
  you were offered — the whole arrangement exists so that a refusal is sayable.

- **Do not report progress you have not made.** Saying `progressed` every run
  while nothing changes looks like attention and is worse than silence, because
  it hides how long the work has actually been stuck. If you did nothing, say
  what stopped you.

If you say it more than once, the last one counts — so if you sketch the format
while thinking aloud, put the real answer at the end.

## Do not

- Poll or write to any task system yourself. You will duplicate what is already
  being recorded, and the two will disagree.
- Loop. Reach a stable point and stop. If you need something, ask for it and
  stop; you will be run again when there is an answer.
- Work outside this directory unless what was asked plainly requires it.
EOF_src_agents
}

src_tool() { cat <<'EOF_src_tool'
#!/usr/bin/env python3
"""One tool, over MCP: say what happened.

The assistants that matter here all speak tool calls, and an assistant asked to
call a tool calls it far more reliably than one asked to remember a file on its
way out. So this is the front door.

**It is still the file underneath.** `report_outcome` writes
`<workspace>/.harness/outcome.json`, which is what the wrapper reads, and that
is deliberate rather than lazy:

- an assistant that reports and then dies has still reported;
- the wrapper reads one thing however the answer arrived, so `declared_outcome`
  stays a single function rather than one per transport;
- an assistant with no tools, or one whose tool mechanism nobody has wired yet,
  works by writing the file itself and nothing downstream can tell.

**It is deliberately not a docket client.** It cannot read the register, take on
work, or post updates. The runner speaks docket; giving the assistant its own
client would put the control loop back inside the agent, hand it the credential
it currently never sees, and re-open the door to reporting nothing usefully
every minute.

Stdlib only, JSON-RPC over stdio, so it can be written into a workspace by a
single-file runner that has no package manager behind it.

    HARNESS_WORKSPACE=/path/to/workspace report-outcome
"""

import json
import os
import pathlib
import sys

OUTCOMES = ("delivered", "progressed", "blocked", "declined", "failed")

TOOL = {
    "name": "report_outcome",
    "description": (
        "Record what happened with the work you took on. Call this before you "
        "stop. Calling it again replaces what you said earlier, so the last "
        "call is the answer."
    ),
    "inputSchema": {
        "type": "object",
        "properties": {
            "outcome": {
                "type": "string",
                "enum": list(OUTCOMES),
                "description": (
                    "delivered: you believe what was asked for is done. "
                    "progressed: you did some of it and it is not finished. "
                    "blocked: you cannot go further without an answer. "
                    "declined: this is not yours to do — a real answer, not a "
                    "failure. failed: you could not work at all."
                ),
            },
            "note": {
                "type": "string",
                "description": "One line. A person reads this later.",
            },
            "question": {
                "type": "string",
                "description": (
                    "Only when blocked. Opened as a real request to the person "
                    "who asked you, and it stays outstanding until they answer. "
                    "Ask one specific thing, not a summary of your confusion."
                ),
            },
        },
        "required": ["outcome", "note"],
    },
}


def outcome_path() -> pathlib.Path:
    ws = pathlib.Path(os.environ.get("HARNESS_WORKSPACE", "."))
    d = ws / ".harness"
    d.mkdir(parents=True, exist_ok=True)
    return d / "outcome.json"


def record(args: dict) -> str:
    outcome = args.get("outcome")
    if outcome not in OUTCOMES:
        # Told, not silently corrected: an assistant that gets a refusal can fix
        # it in the same turn, which is the whole advantage of a tool over a file
        # nobody reads back.
        raise ValueError(f"outcome must be one of {', '.join(OUTCOMES)}; got {outcome!r}")
    note = (args.get("note") or "").strip()
    if not note:
        raise ValueError("note is required — one line that a person can read later")
    body = {"outcome": outcome, "note": note}
    if args.get("question"):
        body["question"] = args["question"].strip()
    if outcome == "blocked" and "question" not in body:
        raise ValueError("blocked needs a question: what do you need answered?")
    outcome_path().write_text(json.dumps(body))
    if outcome == "blocked":
        return f"Recorded: blocked. Your question will be put to them: {body['question']}"
    return f"Recorded: {outcome}. You can stop now."


def reply(rid, result=None, error=None) -> None:
    msg = {"jsonrpc": "2.0", "id": rid}
    msg["error" if error else "result"] = error if error else result
    sys.stdout.write(json.dumps(msg) + "\n")
    sys.stdout.flush()


def main() -> None:
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except json.JSONDecodeError:
            continue
        method, rid = req.get("method"), req.get("id")
        # Notifications carry no id and must not be answered.
        if rid is None:
            continue

        if method == "initialize":
            # Echo the client's protocol version back. These assistants do not
            # agree on which revision they speak, and refusing the ones that ask
            # for a version this file has never heard of would be a way of
            # supporting only whichever was current the day it was written.
            asked = (req.get("params") or {}).get("protocolVersion") or "2025-06-18"
            reply(rid, {
                "protocolVersion": asked,
                "capabilities": {"tools": {}},
                "serverInfo": {"name": "docket-harness", "version": "1"},
            })
        elif method == "tools/list":
            reply(rid, {"tools": [TOOL]})
        elif method == "tools/call":
            params = req.get("params") or {}
            if params.get("name") != TOOL["name"]:
                reply(rid, error={"code": -32602, "message": f"no tool {params.get('name')!r}"})
                continue
            try:
                text = record(params.get("arguments") or {})
            except ValueError as exc:
                reply(rid, {"content": [{"type": "text", "text": str(exc)}], "isError": True})
            else:
                reply(rid, {"content": [{"type": "text", "text": text}]})
        elif method == "ping":
            reply(rid, {})
        else:
            reply(rid, error={"code": -32601, "message": f"no method {method!r}"})


if __name__ == "__main__":
    main()
EOF_src_tool
}

src_wrapper_amplifier() { cat <<'EOF_src_wrapper_amplifier'
#!/usr/bin/env bash
# The `amplifier` CLI -- the modular platform, not `amplifier-agent` beside it.
# They are different programs with different contracts; both are here because
# either may be the thing you have.
#
# Continuation: **captured, and the fallback is implicit.** `run --resume <id>`
# takes an explicit session; `amplifier continue` resumes "the most recent"
# one, which is a fact about the process's own state rather than about this
# subject. The workspace makes the implicit form survivable -- most recent
# *here* is most recent about this -- but the explicit id is preferred whenever
# the run gives one, because "most recent" stops being true the moment anything
# else runs.
#
# Amplifier also carries its own bundles and agents, so the assistant may have a
# task source of its own. That is fine and is the reason this file exists: the
# runner does not need to know, and only this wrapper does.
set -uo pipefail
. "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib.sh"

REQ="$(cat)"
WS="$(printf '%s' "$REQ" | jq -r '.workspace')"
STATE="$WS/.harness/amplifier"; mkdir -p "$STATE"
SESSION_FILE="$STATE/session"

ARGS=(run --output-format json --mode "${AMPLIFIER_MODE:-single}")
[ -n "${AMPLIFIER_BUNDLE:-}" ] && ARGS+=(--bundle "$AMPLIFIER_BUNDLE")
[ -n "${AMPLIFIER_PROVIDER:-}" ] && ARGS+=(--provider "$AMPLIFIER_PROVIDER")
[ -n "${AMPLIFIER_MODEL:-}" ] && ARGS+=(--model "$AMPLIFIER_MODEL")
[ -s "$SESSION_FILE" ] && ARGS+=(--resume "$(cat "$SESSION_FILE")")

cd "$WS" || { failed_result "cannot enter $WS"; exit 0; }
# stdout only. The tools separate their streams and this used to merge them with
# `2>&1`, so a diagnostic line landed in the middle of the data: pi prints
# "Warning: No project session found ... creating a new session" on the first run
# of a session, which made the whole JSONL stream unparseable and sent a slice of
# the prompt to the register as the agent's report. Stderr is left to flow to the
# wrapper's own stderr, which the runner already keeps in the run log.
OUT="$(amplifier "${ARGS[@]}" "$(default_prompt "$REQ")")"; RC=$?
if [ $RC -ne 0 ] && [ -s "$SESSION_FILE" ]; then
  echo "resume failed ($RC); starting fresh" >&2
  rm -f "$SESSION_FILE"
  OUT="$(amplifier run --output-format json --mode "${AMPLIFIER_MODE:-single}" \
         "$(default_prompt "$REQ")")"; RC=$?
fi
printf '%s\n' "$OUT" >&2
debug_dump "$WS" "stdout" "$OUT"

SID="$(printf '%s' "$OUT" | sed -n '/^[[:space:]]*{/,$p' | jq -r '.session_id // .session // empty' 2>/dev/null)"
[ -n "$SID" ] && printf '%s' "$SID" > "$SESSION_FILE"

[ $RC -ne 0 ] && { failed_result "amplifier exited $RC"; exit 0; }

# Stdout opens with a banner -- "Bundle '...' prepared successfully" -- and the
# JSON follows it, pretty-printed. So the envelope starts at the first line that
# begins a JSON object, and anything before it is noise this wrapper is here to
# absorb. Reading from byte zero got the banner and a parse error, and the raw
# tail that came of it was posted to the register as the agent's report.
ENVELOPE="$(printf '%s' "$OUT" | sed -n '/^[[:space:]]*{/,$p')"
REPLY="$(printf '%s' "$ENVELOPE" | jq -r '.response // .result // .content // empty' 2>/dev/null)"
STATUS="$(printf '%s' "$ENVELOPE" | jq -r '.status // empty' 2>/dev/null)"
if [ -n "$STATUS" ] && [ "$STATUS" != "success" ]; then
  failed_result "amplifier reported $STATUS: $(printf '%s' "$ENVELOPE" | jq -r '.error // empty' | head -c 200)"
  exit 0
fi
[ -z "$REPLY" ] && REPLY="$(printf '%s' "$OUT" | tail -c 2000 | tr -d '\000')"
SUMMARY="$(printf '%s' "$REPLY" | head -c 400 | tr '\n' ' ')"

# Three channels, best first. The tool is validated and can refuse a bad call;
# the response is the one every assistant has; the prose heuristic is a last
# resort and may only be wrong towards `progressed`, which leaves the work ours
# and the register honest that nothing moved.
if DECLARED="$(declared_outcome "$WS")"; then
  printf '%s' "$DECLARED" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
if SAID="$(response_outcome "$REPLY")"; then
  printf '%s' "$SAID" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
jq -nc --arg n "${SUMMARY:-ran and said nothing}" '{outcome:"progressed", note:$n}'
EOF_src_wrapper_amplifier
}

src_wrapper_amplifieragent() { cat <<'EOF_src_wrapper_amplifieragent'
#!/usr/bin/env bash
# amplifier-agent — the engine, not the `amplifier` CLI beside it. They are
# different programs; this is the one built to be driven.
#
# Configured with AMPLIFIER_AGENT_PROVIDER / _MODEL / _MODE, deliberately not
# the AMPLIFIER_* names the `amplifier` CLI wrapper uses: they are different
# programs with different provider modules, and a box that runs both would
# otherwise have one variable meaning two things.
#
# Continuation: **caller-chosen id plus an explicit resume**, which is the best
# arrangement of the four here. `--session-id` is ours to pick, so it is derived
# from the subject and never stored; `--resume` says whether to continue the
# transcript, so a first run and a tenth differ by one flag and no bookkeeping
# beyond "have we been here".
#
# Its own docs describe this host exactly: "a subprocess host typically writes
# one file per agent instance and passes --config <path> on every turn". So the
# config, the MCP server and the skills all live in the workspace, which means
# an agent's whole configuration moves with its work and nothing is left behind
# on a machine when the work goes elsewhere.
set -uo pipefail
. "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib.sh"

REQ="$(cat)"
WS="$(printf '%s' "$REQ" | jq -r '.workspace')"
SUBJECT="$(printf '%s' "$REQ" | jq -r '.entry.subject')"
STATE="$WS/.harness/amplifier-agent"; mkdir -p "$STATE"

SESSION_ID="docket-$(printf '%s' "$SUBJECT" | sha256sum | cut -c1-24)"

# The outcome tool, over MCP. The engine takes a path to an MCP file rather than
# inline JSON, so it is written beside the config it is named in.
CONFIG="$STATE/host-config.json"
MCP_FILE="$STATE/mcp.json"
TOOL="$(install_outcome_tool "$WS" || true)"
if [ -n "$TOOL" ]; then
  jq -nc --arg c "$(command -v python3)" --arg a "$TOOL" --arg ws "$WS" \
    '{mcpServers:{harness:{command:$c, args:[$a], env:{HARNESS_WORKSPACE:$ws}}}}' > "$MCP_FILE"
fi

# The top level of this file is closed -- an unknown key is an error rather than
# a warning -- so it is built from exactly the keys the engine documents, and
# `mcp` is omitted entirely when there is no tool to point at.
jq -nc --arg mcp "$MCP_FILE" --arg tool "$TOOL" \
  --arg provider "${AMPLIFIER_AGENT_PROVIDER:-}" --arg model "${AMPLIFIER_AGENT_MODEL:-}" '
  {approval: {mode: "yes"}}
  + (if $tool == "" then {} else {mcp: {configPath: $mcp}} end)
  + (if $provider == "" then {} else
      {provider: ({module: $provider}
        + (if $model == "" then {} else {config: {default_model: $model}} end))}
     end)' > "$CONFIG"

ARGS=(run -y --session-id "$SESSION_ID" --cwd "$WS" --config "$CONFIG"
      --output json --display ndjson)
[ -n "${AMPLIFIER_AGENT_MODE:-}" ] && ARGS+=(--mode "$AMPLIFIER_AGENT_MODE")
# `--resume` is a flag over a saved transcript, not an id, so whether we have
# been here is the only thing worth remembering.
[ -f "$STATE/ran" ] && ARGS+=(--resume)

OUT="$(amplifier-agent "${ARGS[@]}" "$(default_prompt "$REQ")" 2>>"$STATE/display.ndjson")"; RC=$?
if [ $RC -ne 0 ] && [ -f "$STATE/ran" ]; then
  echo "resume failed ($RC); starting the session over" >&2
  RETRY=(); for a in "${ARGS[@]}"; do [ "$a" = "--resume" ] && continue; RETRY+=("$a"); done
  OUT="$(amplifier-agent "${RETRY[@]}" --fresh "$(default_prompt "$REQ")" 2>>"$STATE/display.ndjson")"; RC=$?
fi
printf '%s\n' "$OUT" >&2
debug_dump "$WS" "stdout" "$OUT"
touch "$STATE/ran"

[ $RC -ne 0 ] && { failed_result "amplifier-agent exited $RC"; exit 0; }

# Stdout is one envelope line, and the streams are strictly separated, so this
# needs none of the guessing the other wrappers do about where a summary lives.
ERR="$(printf '%s' "$OUT" | jq -r '.error // empty' 2>/dev/null)"
[ -n "$ERR" ] && { failed_result "$(printf '%s' "$ERR" | head -c 300)"; exit 0; }
REPLY="$(printf '%s' "$OUT" | jq -r '.reply // empty' 2>/dev/null)"
SUMMARY="$(printf '%s' "$REPLY" | head -c 400 | tr '\n' ' ')"

# Three channels, best first. The tool is validated and can refuse a bad call;
# the response is the one every assistant has; the prose heuristic is a last
# resort and may only be wrong towards `progressed`, which leaves the work ours
# and the register honest that nothing moved.
if DECLARED="$(declared_outcome "$WS")"; then
  printf '%s' "$DECLARED" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
if SAID="$(response_outcome "$REPLY")"; then
  printf '%s' "$SAID" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
jq -nc --arg n "${SUMMARY:-ran and said nothing}" '{outcome:"progressed", note:$n}'
EOF_src_wrapper_amplifieragent
}

src_wrapper_claude() { cat <<'EOF_src_wrapper_claude'
#!/usr/bin/env bash
# Claude Code.
#
# Continuation: **captured**. A run prints its own `session_id` in the JSON
# result, and resuming means handing that back with `--resume`. So the id has to
# be kept somewhere between runs, and the workspace is that somewhere -- the
# runner stores nothing on a wrapper's behalf.
#
# The old runner passed `--no-session-persistence`, which meant every tick met
# the task for the first time. Feedback three days later arrived at an assistant
# with no memory of having done the work.
set -uo pipefail
. "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib.sh"

REQ="$(cat)"
WS="$(printf '%s' "$REQ" | jq -r '.workspace')"
STATE="$WS/.harness/claude"; mkdir -p "$STATE"
SESSION_FILE="$STATE/session"

PROMPT="$(default_prompt "$REQ")"
ARGS=(-p "$PROMPT" --output-format json --permission-mode acceptEdits --max-turns "${CLAUDE_MAX_TURNS:-40}")
[ -n "${CLAUDE_MODEL:-}" ] && ARGS+=(--model "$CLAUDE_MODEL")

# The outcome tool, offered over MCP. An assistant asked to call a tool calls it
# far more reliably than one asked to remember a file on its way out -- and an
# invalid call comes back refused, with a reason, in time for it to fix.
#
# Merged with whatever the operator configured rather than replacing it: this is
# one small server, and clobbering somebody's task tools to add it would be a
# poor trade. `--allowedTools` is not optional when `--strict-mcp-config` is on:
# without it the run reaches the model, discovers it may not call the tool,
# explains that politely, and exits 0 -- which is how every tick came to re-do
# the same nothing before that flag existed.
TOOL="$(install_outcome_tool "$WS" || true)"
MCP="${CLAUDE_MCP_CONFIG:-}"
# `--allowedTools` is an allowlist, so naming the MCP server narrows everything
# else *out*. The first real run delivered twice with "verified by inspection
# since running python was not permitted" -- it could write the file and not run
# it, because Bash was no longer on the list. So the list starts with a working
# set and the MCP server is appended to it.
ALLOWED="${CLAUDE_ALLOWED_TOOLS:-Read,Write,Edit,Glob,Grep,Bash,TodoWrite}"
if [ -n "$TOOL" ]; then
  OURS="$(jq -nc --arg c "$(command -v python3)" --arg a "$TOOL" --arg ws "$WS" \
    '{mcpServers:{harness:{command:$c, args:[$a], env:{HARNESS_WORKSPACE:$ws}}}}')"
  if [ -n "$MCP" ]; then
    MCP="$(jq -sc '.[0] * .[1]' <(printf '%s' "$MCP") <(printf '%s' "$OURS"))"
  else
    MCP="$OURS"
  fi
  ALLOWED="${ALLOWED:+$ALLOWED,}mcp__harness"
fi
[ -n "$MCP" ] && ARGS+=(--mcp-config "$MCP" --strict-mcp-config)
[ -n "$ALLOWED" ] && ARGS+=(--allowedTools "$ALLOWED")

# Resume if we have been here before, and fall back to a fresh session if the id
# is stale. A session that has expired must not become a task that never runs.
if [ -s "$SESSION_FILE" ]; then
  ARGS+=(--resume "$(cat "$SESSION_FILE")")
fi

cd "$WS" || { failed_result "cannot enter $WS"; exit 0; }
# stdout only. The tools separate their streams and this used to merge them with
# `2>&1`, so a diagnostic line landed in the middle of the data: pi prints
# "Warning: No project session found ... creating a new session" on the first run
# of a session, which made the whole JSONL stream unparseable and sent a slice of
# the prompt to the register as the agent's report. Stderr is left to flow to the
# wrapper's own stderr, which the runner already keeps in the run log.
OUT="$(claude "${ARGS[@]}")"; RC=$?
if [ $RC -ne 0 ] && [ -s "$SESSION_FILE" ]; then
  echo "resume failed ($RC); starting a fresh session" >&2
  rm -f "$SESSION_FILE"
  FRESH=(); for a in "${ARGS[@]}"; do [ "$a" = "--resume" ] && break; FRESH+=("$a"); done
  OUT="$(claude "${FRESH[@]}")"; RC=$?
fi
printf '%s\n' "$OUT" >&2
debug_dump "$WS" "stdout" "$OUT"

# `--output-format json` is an *array* of events in current versions and was a
# single object in older ones. Both are handled rather than pinned, because a
# wrapper that breaks on an upgrade of the thing it wraps is a wrapper that will
# be broken the day nobody is looking at it.
envelope() { printf '%s' "$OUT" | jq -c 'if type=="array" then (.[] | select(.type=="result")) else . end' 2>/dev/null | tail -1; }
SID="$(envelope | jq -r '.session_id // empty' 2>/dev/null)"
[ -z "$SID" ] && SID="$(printf '%s' "$OUT" | jq -r 'if type=="array" then (.[]|.session_id?) else .session_id end' 2>/dev/null | grep -v '^null$' | head -1)"
[ -n "$SID" ] && printf '%s' "$SID" > "$SESSION_FILE"

if [ $RC -ne 0 ]; then
  failed_result "claude exited $RC"; exit 0
fi

# The model's own summary, not a slice of its JSON. A report made of two hundred
# arbitrary characters is barely better than silence, and that is what the old
# runner was posting every minute when its `jq` path came up empty.
REPLY="$(envelope | jq -r '.result // empty' 2>/dev/null)"
SUBTYPE="$(envelope | jq -r '.subtype // empty' 2>/dev/null)"
if [ -n "$SUBTYPE" ] && [ "$SUBTYPE" != "success" ]; then
  failed_result "run ended $SUBTYPE: $(envelope | jq -r '.result // .error // empty' | head -c 200)"
  exit 0
fi

# The whole reply for parsing -- the outcome block is at the *end* of it, so a
# truncated copy is exactly the wrong thing to look in. The short form is only
# ever the note.
SUMMARY="$(printf '%s' "$REPLY" | head -c 400)"
[ -z "$SUMMARY" ] && SUMMARY="ran, but said nothing a summary could be made of"

# Three channels, best first. The tool is validated and can refuse a bad call;
# the response is the one every assistant has; the prose heuristic below is a
# last resort. Its own note beats ours, so the summary is kept only when it
# left none.
if DECLARED="$(declared_outcome "$WS")"; then
  printf '%s' "$DECLARED" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
if SAID="$(response_outcome "$REPLY")"; then
  printf '%s' "$SAID" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi

# It did not say. Read its prose for a blocker rather than reporting progress
# that may not have happened -- a heuristic, and allowed to be wrong only in the
# safe direction: a missed blocker becomes `progressed`, which leaves the work
# ours and leaves the register honest that nothing moved.
if printf '%s' "$SUMMARY" | grep -qiE "need(s)? (a )?(decision|input|clarif)|blocked|cannot proceed|unable to proceed"; then
  jq -nc --arg n "$SUMMARY" '{outcome:"blocked", note:$n, question:$n}'
else
  jq -nc --arg n "$SUMMARY" '{outcome:"progressed", note:$n}'
fi
EOF_src_wrapper_claude
}

src_wrapper_claudecoder() { cat <<'EOF_src_wrapper_claudecoder'
#!/usr/bin/env bash
# Claude Code, set up to write code rather than to answer.
#
# The difference from `claude` is not the model, it is what the assistant is
# given and what it is told:
#
#   - the language tools. `LSP` and `Task` are on the allowlist, so it can ask
#     the language server where a symbol is used instead of grepping for the
#     string and hoping. Coding runs are also allowed more turns, because a real
#     change is read-edit-build-test and each of those is a turn.
#   - the workflow. A coding assistant that does not know its working directory
#     persists will clone the repository again every run, and one that does not
#     know the directory is *its own* will be shy about writing in it. Both are
#     failures of briefing rather than of ability, so this ships the briefing.
#
# Everything else -- how an outcome is reported, how a session resumes -- is the
# same as every other wrapper, which is the point of there being a contract.
set -uo pipefail
. "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib.sh"

REQ="$(cat)"
WS="$(printf '%s' "$REQ" | jq -r '.workspace')"
STATE="$WS/.harness/claude-coder"; mkdir -p "$STATE"
SESSION_FILE="$STATE/session"

# The briefing, written beside the general one on every run so an edit here
# reaches every agent without redeploying anything.
cat > "$WS/CODING.md" <<'BRIEF'
# Working on code here

## This directory is yours, and it persists

You are in a working directory that belongs to **this one piece of work**. It is
still here next time you are asked about the same thing, with whatever you left
in it. So:

- **Look before you fetch.** If the repository you need is already cloned here,
  use it — pull, do not clone again. Re-cloning every run throws away branches,
  build caches and anything uncommitted.
- **Write freely.** This is not a shared checkout and nothing else is using it.
- **Keep scratch work.** Notes, a plan, a failing test you have not fixed yet:
  leave them. Future-you reads them.

If the work needs a repository nobody has cloned yet, clone it here. `git` and a
`GITHUB_TOKEN` are available.

## Use the language server

`LSP` is available and is better than grep for anything structural: where a
symbol is defined, everywhere it is used, what the type is, what the compiler
already thinks is wrong. Reach for it before reading whole files, and read the
diagnostics before deciding you are finished.

## Finish like an engineer

- **Run the tests.** A change you have not run is a claim, and `delivered` is
  supposed to mean more than that.
- **Read the diagnostics** after editing, not before.
- **Do not commit or push unless you were asked to.** If you were: work on a
  branch, never on the default one, and say in your note what you pushed.
- If you cannot build or test — a missing toolchain, no network — that is
  `blocked` with a specific question, not `delivered` with a caveat.

## Scope

Do what was asked and stop. A refactor nobody requested is not a bonus; it is a
larger diff for somebody else to review. If you find something else wrong, say so
in your note rather than fixing it.
BRIEF

PROMPT="$(default_prompt "$REQ")
Read CODING.md in this directory before you start. It describes how this
workspace is used and what finishing means here."

ARGS=(-p "$PROMPT" --output-format json --permission-mode acceptEdits
      --max-turns "${CLAUDE_MAX_TURNS:-80}")
[ -n "${CLAUDE_MODEL:-}" ] && ARGS+=(--model "$CLAUDE_MODEL")

TOOL="$(install_outcome_tool "$WS" || true)"
MCP="${CLAUDE_MCP_CONFIG:-}"
# Wider than the general wrapper's: this one is meant to navigate a codebase and
# build it. `--allowedTools` is an allowlist, so anything absent is refused --
# which is how the first real run came to deliver twice having never been able
# to run the tests it claimed to have checked.
ALLOWED="${CLAUDE_ALLOWED_TOOLS:-Read,Write,Edit,Glob,Grep,Bash,TodoWrite,LSP,Task,WebFetch,WebSearch}"
if [ -n "$TOOL" ]; then
  OURS="$(jq -nc --arg c "$(command -v python3)" --arg a "$TOOL" --arg ws "$WS" \
    '{mcpServers:{harness:{command:$c, args:[$a], env:{HARNESS_WORKSPACE:$ws}}}}')"
  if [ -n "$MCP" ]; then
    MCP="$(jq -sc '.[0] * .[1]' <(printf '%s' "$MCP") <(printf '%s' "$OURS"))"
  else
    MCP="$OURS"
  fi
  ALLOWED="$ALLOWED,mcp__harness"
fi
[ -n "$MCP" ] && ARGS+=(--mcp-config "$MCP" --strict-mcp-config)
ARGS+=(--allowedTools "$ALLOWED")
[ -s "$SESSION_FILE" ] && ARGS+=(--resume "$(cat "$SESSION_FILE")")

cd "$WS" || { failed_result "cannot enter $WS"; exit 0; }
OUT="$(claude "${ARGS[@]}")"; RC=$?
if [ $RC -ne 0 ] && [ -s "$SESSION_FILE" ]; then
  echo "resume failed ($RC); starting a fresh session" >&2
  rm -f "$SESSION_FILE"
  FRESH=(); for a in "${ARGS[@]}"; do [ "$a" = "--resume" ] && break; FRESH+=("$a"); done
  OUT="$(claude "${FRESH[@]}")"; RC=$?
fi
printf '%s\n' "$OUT" >&2
debug_dump "$WS" "stdout" "$OUT"

envelope() { printf '%s' "$OUT" | jq -c 'if type=="array" then (.[] | select(.type=="result")) else . end' 2>/dev/null | tail -1; }
SID="$(envelope | jq -r '.session_id // empty' 2>/dev/null)"
[ -n "$SID" ] && printf '%s' "$SID" > "$SESSION_FILE"
[ $RC -ne 0 ] && { failed_result "claude exited $RC"; exit 0; }

REPLY="$(envelope | jq -r '.result // empty' 2>/dev/null)"
SUBTYPE="$(envelope | jq -r '.subtype // empty' 2>/dev/null)"
if [ -n "$SUBTYPE" ] && [ "$SUBTYPE" != "success" ]; then
  failed_result "run ended $SUBTYPE: $(printf '%s' "$REPLY" | head -c 200)"; exit 0
fi
SUMMARY="$(printf '%s' "$REPLY" | head -c 400)"
[ -z "$SUMMARY" ] && SUMMARY="ran, but said nothing a summary could be made of"

if DECLARED="$(declared_outcome "$WS")"; then
  printf '%s' "$DECLARED" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
if SAID="$(response_outcome "$REPLY")"; then
  printf '%s' "$SAID" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
if printf '%s' "$SUMMARY" | grep -qiE "need(s)? (a )?(decision|input|clarif)|blocked|cannot proceed|unable to proceed"; then
  jq -nc --arg n "$SUMMARY" '{outcome:"blocked", note:$n, question:$n}'
else
  jq -nc --arg n "$SUMMARY" '{outcome:"progressed", note:$n}'
fi
EOF_src_wrapper_claudecoder
}

src_wrapper_echo() { cat <<'EOF_src_wrapper_echo'
#!/usr/bin/env bash
# A wrapper that runs no assistant at all.
#
# For exercising the runner: the contract is a subprocess and a JSON shape, so
# the whole loop can be driven without a model, an API key, or a minute of
# waiting. Set HARNESS_ECHO_OUTCOME to whichever branch you want to see.
#
# It is also the shortest possible answer to "what does a wrapper have to do".
set -uo pipefail
REQ="$(cat)"
echo "echo wrapper saw: $(printf '%s' "$REQ" | jq -c '{entry: .entry.id, state: .entry.state, ws: .workspace}')" >&2
printf '%s' "$REQ" | jq -r '.workspace' | xargs -I{} mkdir -p {}/.harness/echo

case "${HARNESS_ECHO_OUTCOME:-progressed}" in
  blocked) jq -nc '{outcome:"blocked", note:"needs a decision",
                   question:"Which of the two approaches did you want?"}' ;;
  declined) jq -nc '{outcome:"declined", note:"outside what I am set up to do"}' ;;
  delivered) jq -nc '{outcome:"delivered", note:"done"}' ;;
  failed) exit 3 ;;
  *) jq -nc '{outcome:"progressed", note:"had a look, nothing finished"}' ;;
esac
EOF_src_wrapper_echo
}

src_wrapper_opencode() { cat <<'EOF_src_wrapper_opencode'
#!/usr/bin/env bash
# opencode.
#
# Continuation: **captured, but scoped by directory.** `run -s <id>` continues a
# named session and `--continue` takes the last one; `--dir` decides which
# project that is. Since every subject already has its own workspace, `--dir`
# plus `--continue` is enough on its own -- the last session in this directory is
# by construction the last session about this subject.
#
# The id is still recorded when the output offers one, because `--continue` is a
# statement about recency and an explicit id is a statement about identity, and
# the second survives somebody else running opencode in the same directory.
set -uo pipefail
. "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib.sh"

REQ="$(cat)"
WS="$(printf '%s' "$REQ" | jq -r '.workspace')"
STATE="$WS/.harness/opencode"; mkdir -p "$STATE"
SESSION_FILE="$STATE/session"

ARGS=(run --dir "$WS" --format json)
[ -n "${OPENCODE_MODEL:-}" ] && ARGS+=(--model "$OPENCODE_MODEL")
[ -n "${OPENCODE_AGENT:-}" ] && ARGS+=(--agent "$OPENCODE_AGENT")
if [ -s "$SESSION_FILE" ]; then
  ARGS+=(--session "$(cat "$SESSION_FILE")")
elif [ -d "$WS/.opencode" ]; then
  ARGS+=(--continue)
fi

# stdout only. The tools separate their streams and this used to merge them with
# `2>&1`, so a diagnostic line landed in the middle of the data: pi prints
# "Warning: No project session found ... creating a new session" on the first run
# of a session, which made the whole JSONL stream unparseable and sent a slice of
# the prompt to the register as the agent's report. Stderr is left to flow to the
# wrapper's own stderr, which the runner already keeps in the run log.
OUT="$(opencode "${ARGS[@]}" "$(default_prompt "$REQ")")"; RC=$?
if [ $RC -ne 0 ] && [ -s "$SESSION_FILE" ]; then
  echo "continuing failed ($RC); starting fresh" >&2
  rm -f "$SESSION_FILE"
  OUT="$(opencode run --dir "$WS" --format json "$(default_prompt "$REQ")")"; RC=$?
fi
printf '%s\n' "$OUT" >&2
debug_dump "$WS" "stdout" "$OUT"

SID="$(printf '%s' "$OUT" | jq -rs '[.[]? | (.sessionID? // .session_id? // .id? // empty)] | first // empty' 2>/dev/null)"
[ -n "$SID" ] && printf '%s' "$SID" > "$SESSION_FILE"

[ $RC -ne 0 ] && { failed_result "opencode exited $RC"; exit 0; }

# JSONL of events. The reply is every `text` event's part, in order -- one
# assistant turn can be split across several. The first version took whatever
# `.text` or `.content` it found last, which was usually a `tool_use` event, so
# the register was posted the arguments of a file write as the agent's report.
REPLY="$(printf '%s' "$OUT" | jq -rs '[.[] | select(.type=="text") | .part.text? // empty] | join("")' 2>/dev/null)"
[ -z "$REPLY" ] && REPLY="$(printf '%s' "$OUT" | tail -c 2000 | tr -d '\000')"
SUMMARY="$(printf '%s' "$REPLY" | head -c 400 | tr '\n' ' ')"

# Three channels, best first. The tool is validated and can refuse a bad call;
# the response is the one every assistant has; the prose heuristic is a last
# resort and may only be wrong towards `progressed`, which leaves the work ours
# and the register honest that nothing moved.
if DECLARED="$(declared_outcome "$WS")"; then
  printf '%s' "$DECLARED" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
if SAID="$(response_outcome "$REPLY")"; then
  printf '%s' "$SAID" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
jq -nc --arg n "${SUMMARY:-ran and said nothing}" '{outcome:"progressed", note:$n}'
EOF_src_wrapper_opencode
}

src_wrapper_pi() { cat <<'EOF_src_wrapper_pi'
#!/usr/bin/env bash
# pi.
#
# Continuation: **derived, not stored.** `--session-id <id>` uses that exact
# session and creates it if it is missing, so the id can be computed from the
# subject and there is nothing to keep, nothing to lose, and nothing to go stale.
# The first run and the tenth are the same command.
#
# This is why the contract lets a wrapper store nothing: making every wrapper
# hand an opaque blob back to the runner would have invented state that pi does
# not need.
set -uo pipefail
. "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib.sh"

REQ="$(cat)"
WS="$(printf '%s' "$REQ" | jq -r '.workspace')"
SUBJECT="$(printf '%s' "$REQ" | jq -r '.entry.subject')"
mkdir -p "$WS/.harness/pi"

# Stable for a subject, and a valid session id wherever it is run. Same input,
# same session, forever.
SESSION_ID="$(printf '%s' "$SUBJECT" | sha256sum | cut -c1-32 \
              | sed -E 's/(.{8})(.{4})(.{4})(.{4})(.{12})/\1-\2-\3-\4-\5/')"

ARGS=(--print --mode json --session-id "$SESSION_ID" --session-dir "$WS/.harness/pi")
[ -n "${PI_PROVIDER:-}" ] && ARGS+=(--provider "$PI_PROVIDER")
[ -n "${PI_MODEL:-}" ] && ARGS+=(--model "$PI_MODEL")

cd "$WS" || { failed_result "cannot enter $WS"; exit 0; }
# stdout only. The tools separate their streams and this used to merge them with
# `2>&1`, so a diagnostic line landed in the middle of the data: pi prints
# "Warning: No project session found ... creating a new session" on the first run
# of a session, which made the whole JSONL stream unparseable and sent a slice of
# the prompt to the register as the agent's report. Stderr is left to flow to the
# wrapper's own stderr, which the runner already keeps in the run log.
OUT="$(pi "${ARGS[@]}" "$(default_prompt "$REQ")")"; RC=$?
printf '%s\n' "$OUT" >&2
debug_dump "$WS" "stdout" "$OUT"

[ $RC -ne 0 ] && { failed_result "pi exited $RC"; exit 0; }

# `--mode json` shape is not guaranteed across versions, so take the first thing
# that looks like a summary and fall back to the raw tail rather than reporting
# nothing.
# JSONL of events. The reply is the text of the last assistant `message_end`,
# and `agent_end.messages` carries the same thing if the stream was cut short.
#
# The first version reached for any `.text` or `.content` it could find, which
# matched the *prompt echoed back in the user message* -- so the register was
# posted a slice of its own instructions as the agent's report.
REPLY="$(printf '%s' "$OUT" | jq -rs '
  ([.[] | select(.type=="message_end") | .message | select(.role=="assistant")] | last)
  // ([.[] | select(.type=="agent_end") | .messages[]? | select(.role=="assistant")] | last)
  | [.content[]? | select(.type=="text") | .text] | join("")' 2>/dev/null)"
[ -z "$REPLY" ] || [ "$REPLY" = "null" ] && REPLY="$(printf '%s' "$OUT" | tail -c 2000 | tr -d '\000')"
SUMMARY="$(printf '%s' "$REPLY" | head -c 400 | tr '\n' ' ')"

# Three channels, best first. The tool is validated and can refuse a bad call;
# the response is the one every assistant has; the prose heuristic is a last
# resort and may only be wrong towards `progressed`, which leaves the work ours
# and the register honest that nothing moved.
if DECLARED="$(declared_outcome "$WS")"; then
  printf '%s' "$DECLARED" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
if SAID="$(response_outcome "$REPLY")"; then
  printf '%s' "$SAID" | jq -c --arg s "$SUMMARY" '.note = (if .note == "" then $s else .note end)'
  exit 0
fi
jq -nc --arg n "${SUMMARY:-ran and said nothing}" '{outcome:"progressed", note:$n}'
EOF_src_wrapper_pi
}


# Aliases, because the assistants are known by more than one name and being told
# "unknown harness: claude-code" when you asked for the thing you have installed
# is a poor welcome.
# A wrapper is an executable implementing the contract in harness/README.md, so
# "installing a new one" is bundling a file rather than resolving a package. A
# path or a URL is therefore as good as a name, and anybody can ship a wrapper
# for an assistant nobody here has heard of without touching this repository.
CUSTOM=""
case "$HARNESS" in
  http://*|https://*)
    CUSTOM="$(curl -fsSL "$HARNESS")" || die "could not fetch $HARNESS"
    : "${NAME:=docket-$(basename "${HARNESS%%\?*}")}" ;;
  ./*|/*|../*)
    [ -r "$HARNESS" ] || die "no wrapper at $HARNESS"
    CUSTOM="$(cat "$HARNESS")"
    : "${NAME:=docket-$(basename "$HARNESS")}" ;;
esac
if [ -n "$CUSTOM" ]; then
  printf '%s' "$CUSTOM" | head -1 | grep -q '^#!' \
    || die "that does not look like a wrapper: no #! on the first line"
fi

# Shell function names cannot hold a hyphen, so the embedded wrappers are named
# without one and the names people actually type are mapped here. Being told
# "unknown harness: amplifier-agent" when that is exactly what you have would be
# a poor welcome.
case "$HARNESS" in
  claude-coder|claudecoder|coder)    HARNESS=claudecoder ;;
  claude|claude-code|claudecode)     HARNESS=claude ;;
  pi)                                HARNESS=pi ;;
  opencode|open-code)                HARNESS=opencode ;;
  amplifier-agent|amplifieragent)    HARNESS=amplifieragent ;;
  amplifier|amplifier-cli)           HARNESS=amplifier ;;
esac

# What to call each on the way out. `amplifieragent` is an implementation
# detail of bash and should not be the name anybody reads.
display_name() {
  case "$1" in
    amplifieragent) echo amplifier-agent ;;
    claudecoder)    echo claude-coder ;;
    claude)         echo claude-code ;;
    *)              echo "$1" ;;
  esac
}
AVAILABLE="$(for f in $(declare -F | sed -n 's/^declare -f src_wrapper_//p' | sort); do display_name "$f"; done | tr '\n' ' ')"
if [ -n "${LIST:-}" ]; then
  printf 'harnesses: %s\n' "$AVAILABLE"; exit 0
fi
[ -n "$HARNESS" ] || die "which assistant? --harness <${AVAILABLE// /|}>, or a path or URL"
if [ -z "$CUSTOM" ]; then
  declare -F "src_wrapper_$HARNESS" >/dev/null \
    || die "no harness '$HARNESS'; have: $AVAILABLE (or pass a path or URL)"
  command -v "$(display_name "$HARNESS")" >/dev/null 2>&1 \
    || command -v "$HARNESS" >/dev/null 2>&1 \
    || printf 'install: note — %s is not on PATH yet; the runner will need it\n' \
       "$(display_name "$HARNESS")" >&2
fi

: "${NAME:=docket-$(display_name "$HARNESS")}"
mkdir -p "$DEST" || die "cannot create $DEST"
OUT="$DEST/$NAME"

# The bundle. `. lib.sh` lines go, because the library is already above them;
# everything else is verbatim, so what runs here is what was tested there.
strip_source() { grep -v '^\. "\$(cd .*lib\.sh"$' | grep -v '^# shellcheck source=harness/lib.sh$' | grep -v '^\. "\$HERE/lib\.sh"$'; }

{
  printf '#!/usr/bin/env bash\n'
  printf '# docket runner for %s. Generated by install.sh; edit nothing here.\n' "$HARNESS"
  printf '#\n'
  printf '#   DOCKET_URL=https://docket.example DOCKET_API_KEY=dk_… %s\n' "$NAME"
  printf '#\n'
  printf '# DOCKET_API_KEY may be a credential (dk_) or a single-use ticket (dke_),\n'
  printf '# which is spent once and replaced by the credential it buys.\n'
  printf 'set -uo pipefail\n\n'

  printf 'HARNESS_AGENTS_MD_INLINE=1\n'
  printf 'HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"\n\n'

  printf '# ---- library ----\n'; src_lib | strip_source

  printf '\n# ---- the instructions handed to the assistant ----\n'
  printf 'write_agents_md() {\n  cat > "$1" <<'"'"'EOF_AGENTS'"'"'\n'
  src_agents
  printf 'EOF_AGENTS\n}\n'

  printf '\n# ---- the outcome tool, offered over MCP where the assistant speaks it ----\n'
  printf 'write_outcome_tool() {\n  cat > "$1" <<'"'"'EOF_TOOL'"'"'\n'
  src_tool
  printf 'EOF_TOOL\n}\n'

  printf '\n# ---- wrapper: %s ----\n' "${CUSTOM:+custom }$(display_name "$HARNESS")"
  # Not indented. It would read better inside the braces and a wrapper is
  # allowed to contain a heredoc, whose terminator must start at column zero --
  # indenting the body silently turns `BRIEF` into `  BRIEF` and the whole file
  # stops parsing at the end.
  printf 'wrapper_main() {\n'
  if [ -n "$CUSTOM" ]; then
    printf '%s' "$CUSTOM" | strip_source
  else
    "src_wrapper_$HARNESS" | strip_source
  fi
  printf '\n}\n'
  printf 'if [ "${HARNESS_ROLE:-}" = "wrapper" ]; then wrapper_main; exit $?; fi\n'

  printf '\n# ---- runner ----\n'
  printf 'HARNESS_WRAPPER="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/%s"\n' "$NAME"
  printf 'export HARNESS_WRAPPER\n'
  src_runner | strip_source
} > "$OUT"
chmod +x "$OUT"

printf 'installed %s\n' "$OUT"
case ":$PATH:" in
  *":$DEST:"*) ;;
  *) printf 'note: %s is not on your PATH\n' "$DEST" >&2 ;;
esac
printf '\nnext:\n  export DOCKET_URL=https://docket.example\n'
printf '  export DOCKET_API_KEY=dke_…      # a ticket from /board/access\n'
printf '  %s\n' "$NAME"
